  | H : (_ =? _)%Z = true |- _ => apply Z.eqb_eq in H
  | H : ((_ <=? _) = true \/ _) |- _ => destruct H as [H|H]
  | H : (_ \/ (_ <=? _) = true) |- _ => destruct H as [H|H] end).

